    INSERT INTO activities (lesson_id,activity_type,sort_order,turn_id,word_id,prompt,instruction,difficulty,config,metadata) VALUES (v_l_4,'word_order',16,NULL,NULL,'I work on Holiday and Monday','واژه‌ها را با لمس به ترتیب درست بچین.',1,CAST('{"mode":"tap_tokens","tokens":["Monday","on","I","Holiday","work","and"],"answer":["I","work","on","Holiday","and","Monday"],"input":"tap_tokens","scored":true}' AS JSON),JSON_OBJECT('phase','controlled_production','typing',FALSE));
    INSERT INTO activities (lesson_id,activity_type,sort_order,turn_id,word_id,prompt,instruction,difficulty,config,metadata) VALUES (v_l_4,'speak',17,NULL,NULL,'در مصاحبه کوتاه کاری، موسیقی صبح و بعدازظهرت را بگو: صبح کار و پیش از استراحت نشستن.','در این موقعیت، پاسخ مناسب را با صدا بگو.',1,CAST('{"mode":"scenario_transfer","scenario_fa":"در مصاحبه کوتاه کاری، موسیقی صبح و بعدازظهرت را بگو: صبح کار و پیش از استراحت نشستن.","accepted_intents":["I work in the morning and sit before break.","In the morning I work; before break I sit."],"evaluation":"stt","input":"speech","scored":true,"independent":true}' AS JSON),JSON_OBJECT('phase','transfer','typing',FALSE,'novelScenario',TRUE,'masteryCheck',TRUE));
    INSERT INTO activities (lesson_id,activity_type,sort_order,turn_id,word_id,prompt,instruction,difficulty,config,metadata) VALUES (v_l_4,'speak',18,NULL,NULL,'مسئول شیفت درباره تعطیلات و دویکشنبه می‌پرسد؛ تایید کن که هر دو روز کار می‌کنی.','در این موقعیت، پاسخ مناسب را با صدا بگو.',1,CAST('{"mode":"scenario_transfer","scenario_fa":"مسئول شیفت درباره تعطیلات و دویکشنبه می‌پرسد؛ تایید کن که هر دو روز کار می‌کنی.","accepted_intents":["Yes, I work on Holiday and Monday.","I work both Holiday and Monday."],"evaluation":"stt","input":"speech","scored":true,"independent":true}' AS JSON),JSON_OBJECT('phase','transfer','typing',FALSE,'novelScenario',TRUE,'masteryCheck',TRUE));
  ELSEIF v_count=1 THEN
    SELECT id INTO v_chapter FROM chapters WHERE module_id=v_module AND sort_order=8;
    IF (SELECT COUNT(*) FROM lessons WHERE chapter_id=v_chapter)<>4 OR (SELECT COUNT(*) FROM turns t JOIN lessons l ON l.id=t.lesson_id WHERE l.chapter_id=v_chapter)<>42 OR (SELECT COUNT(*) FROM activities a JOIN lessons l ON l.id=a.lesson_id WHERE l.chapter_id=v_chapter)<>72 OR JSON_UNQUOTE(JSON_EXTRACT((SELECT metadata FROM chapters WHERE id=v_chapter),'$.stageId'))<>'en-fa-a1-series-0008' THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Existing chapter does not match validated stage'; END IF;
  ELSE SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Chapter identity is not unique'; END IF;
  IF (SELECT COUNT(*) FROM lessons WHERE chapter_id=v_chapter)<>4 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Chapter must contain exactly four lessons'; END IF;
  IF EXISTS (SELECT 1 FROM lessons l LEFT JOIN turns t ON t.lesson_id=l.id WHERE l.chapter_id=v_chapter GROUP BY l.id HAVING COUNT(t.id)<8 OR COUNT(t.id)>14) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Turn quota failed'; END IF;
  IF EXISTS (SELECT 1 FROM lessons l LEFT JOIN activities a ON a.lesson_id=l.id WHERE l.chapter_id=v_chapter GROUP BY l.id HAVING COUNT(a.id)<12 OR COUNT(a.id)>18) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Activity quota failed'; END IF;
  COMMIT;
END$$
CALL import_nova_en_series_008()$$
